# -*- coding: utf-8 -*-
# b2u6 — Nuances and idioms: practice sentences, 12 per lesson.
DRILLS = {
 "b2u6l1": [
  ("So, how did that thing with your boss end?", "สรุปแล้วเรื่องกับหัวหน้าของคุณจบยังไง?", "sà-rùp lɛ́ɛo rʉ̂ang kàp hǔa-nâa khɔ̌ɔng khun jòp yang-ngai?"),
  ("I mean, are you saying you're not coming to our party tonight?", "หมายความว่าคุณจะไม่มางานปาร์ตี้ของเราคืนนี้เหรอ?", "mǎai-khwaam-wâa khun jà mâi maa ngaan-paa-tîi khɔ̌ɔng rao khʉʉn-níi rə̌ə?"),
  ("I'm not tired at all; we can keep going!", "ฉันไม่เหนื่อยเลยสักนิด ทำต่อได้!", "chǎn mâi nʉ̀ai ləəi sàk-nít, tham tɔ̀ɔ dâi!"),
  ("If only I had more free time!", "ถ้าฉันมีเวลาว่างมากกว่านี้ก็ดีสิ!", "thâa chǎn mii wee-laa-wâang mâak-kwàa níi kɔ̂ɔ dii sì!"),
  ("I don't know, ask Malee; she definitely knows.", "ไม่รู้สิ ถามมาลีดู เธอรู้แน่นอน", "mâi rúu sì, thǎam maa-lii duu, thəə rúu nɛ̂ɛ-nɔɔn"),
  ("Come on, hurry up, the movie starts in five minutes!", "เร็วเข้า รีบหน่อย หนังจะเริ่มในอีกห้านาที!", "reo khâo, rîip nɔ̀i, nǎng jà rə̂əm nai ìik hâa naa-thii!"),
  ("Don't mention it; for a friend I'd do even more than this.", "ไม่เป็นไร เพื่อเพื่อนฉันทำได้มากกว่านี้อีก", "mâi pen-rai, phʉ̂a phʉ̂an chǎn tham dâi mâak-kwàa níi ìik"),
  ("This is so boring, we have to redo everything from the beginning!", "น่าเบื่อจริงๆ เราต้องทำใหม่หมดตั้งแต่ต้น!", "nâa-bʉ̀a jing-jing, rao tɔ̂ng tham mài mòt tâng-tɛ̀ɛ tôn!"),
  ("Please put all that stuff in the closet.", "ช่วยเอาของพวกนั้นทั้งหมดไปใส่ตู้หน่อย", "chûai ao khɔ̌ɔng phûak nán tháng-mòt pai sài tûu nɔ̀i"),
  ("This summer I read a lot of books.", "หน้าร้อนนี้ฉันอ่านหนังสือไปเยอะมาก", "nâa-rɔ́ɔn níi chǎn àan nǎng-sʉ̌ʉ pai yə́ mâak"),
  ("I mean, you spent a lot of money for nothing?", "หมายความว่าคุณเสียเงินไปเยอะแยะโดยเปล่าประโยชน์เหรอ?", "mǎai-khwaam-wâa khun sǐa ngən pai yə́-yɛ́ dooi plào-prà-yòot rə̌ə?"),
  ("If only the weather were nice tomorrow and we could go to the mountains!", "ถ้าพรุ่งนี้อากาศดีและเราได้ไปเที่ยวภูเขาก็คงดี!", "thâa phrûng-níi aa-kàat dii lɛ́ rao dâi pai thîao phuu-khǎo kɔ̂ɔ khong dii!"),
 ],
 "b2u6l2": [
  ("I wish you luck on your exam tomorrow!", "ขอให้โชคดีกับการสอบพรุ่งนี้นะ!", "khɔ̌ɔ hâi chôok-dii kàp kaan-sɔ̀ɔp phrûng-níi ná!"),
  ("That bag is very expensive; I'm not buying it.", "กระเป๋าใบนั้นแพงมาก ฉันไม่ซื้อหรอก", "krà-pǎo bai nán phɛɛng mâak, chǎn mâi sʉ́ʉ rɔ̀ɔk"),
  ("I have no money until the end of the month; can you lend me a little?", "ฉันไม่มีเงินจนถึงสิ้นเดือน ให้ยืมหน่อยได้ไหม?", "chǎn mâi mii ngən jon-thʉ̌ng sîn-dʉan, hâi yʉʉm nɔ̀i dâi mǎi?"),
  ("Don't make fun of me; this time I'm serious!", "อย่าล้อฉันเลย ครั้งนี้ฉันพูดจริงจังนะ!", "yàa lɔ́ɔ chǎn ləəi, khráng-níi chǎn phûut jing-jang ná!"),
  ("Sorry, my mind was somewhere else; I didn't hear you.", "ขอโทษที ใจลอยไปไหนก็ไม่รู้ ไม่ได้ยินที่คุณพูด", "khɔ̌ɔ-thôot thii, jai-lɔɔi pai nǎi kɔ̂ɔ mâi rúu, mâi dâi-yin thîi khun phûut"),
  ("The children are impatiently waiting for summer vacation to start.", "เด็กๆ รอปิดเทอมหน้าร้อนอย่างใจจดใจจ่อ", "dèk-dèk rɔɔ pìt-thəəm nâa-rɔ́ɔn yàang jai-jòt-jai-jɔ̀ɔ"),
  ("My mother goes to great lengths for everyone, but nobody thanks her.", "แม่ทุ่มเทให้ทุกคนสุดตัว แต่ไม่มีใครขอบคุณแม่เลย", "mɛ̂ɛ thûm-thee hâi thúk-khon sùt-tua, tɛ̀ɛ mâi mii khrai khɔ̀ɔp-khun mɛ̂ɛ ləəi"),
  ("At a rough guess, the trip will take at least three hours.", "กะคร่าวๆ การเดินทางน่าจะใช้เวลาอย่างน้อยสามชั่วโมง", "kà khrâao-khrâao, kaan-dəən-thaang nâa-jà chái wee-laa yàang-nɔ́ɔi sǎam chûa-moong"),
  ("He finished his homework in the blink of an eye.", "เขาทำการบ้านเสร็จในพริบตาเดียว", "kháo tham kaan-bâan sèt nai phríp-taa diao"),
  ("Somchai said that car had cost him a lot of money.", "สมชายบอกว่ารถคันนั้นทำให้เขาหมดเงินไปเยอะ", "sǒm-chaai bɔ̀ɔk wâa rót khan nán tham-hâi kháo mòt ngən pai yə́"),
  ("Why do you all always make fun of me in front of everyone?", "ทำไมพวกคุณชอบล้อฉันต่อหน้าคนอื่นตลอด?", "tham-mai phûak-khun chɔ̂ɔp lɔ́ɔ chǎn tɔ̀ɔ-nâa khon ʉ̀ʉn tà-lɔ̀ɔt?"),
  ("You all went to great lengths to organize the celebration, thank you!", "ทุกคนทุ่มเทกันมากเพื่อจัดงานฉลองนี้ ขอบคุณนะ!", "thúk-khon thûm-thee kan mâak phʉ̂a jàt ngaan-chà-lɔ̌ɔng níi, khɔ̀ɔp-khun ná!"),
 ],
 "b2u6l3": [
  ("Not everyone understands irony, especially in written messages.", "ไม่ใช่ทุกคนจะเข้าใจการประชด โดยเฉพาะในข้อความที่เขียน", "mâi châi thúk-khon jà khâo-jai kaan-prà-chót, dooi-chà-phɔ́ nai khɔ̂ɔ-khwaam thîi khǐan"),
  ("His sarcasm sometimes hurts even more than an insult.", "คำประชดประชันของเขาบางครั้งก็เจ็บยิ่งกว่าคำด่า", "kham prà-chót-prà-chan khɔ̌ɔng kháo baang-khráng kɔ̂ɔ jèp yîng kwàa kham dàa"),
  ("He made a joke and the whole room burst out laughing.", "เขาเล่ามุกแล้วทั้งห้องก็หัวเราะลั่น", "kháo lâo múk lɛ́ɛo tháng hɔ̂ng kɔ̂ɔ hǔa-rɔ́ lân"),
  ("This phrase has two meanings; be careful when you use it.", "ประโยคนี้มีสองความหมาย ระวังเวลาใช้ด้วยนะ", "prà-yòok níi mii sɔ̌ɔng khwaam-mǎai, rá-wang wee-laa chái dûai ná"),
  ("He takes everything, even jokes, very seriously.", "เขาจริงจังกับทุกเรื่องมาก แม้แต่เรื่องล้อเล่น", "kháo jing-jang kàp thúk rʉ̂ang mâak, mɛ́ɛ-tɛ̀ɛ rʉ̂ang lɔ́ɔ-lên"),
  ("Were you offended by what I said at the meeting yesterday?", "คุณไม่พอใจที่ฉันพูดในที่ประชุมเมื่อวานหรือเปล่า?", "khun mâi phɔɔ-jai thîi chǎn phûut nai thîi-prà-chum mʉ̂a-waan rʉ̌ʉ-plào?"),
  ("Being able to joke about yourself is a sign of intelligence.", "การที่เราล้อตัวเองได้เป็นสัญญาณของความฉลาด", "kaan thîi rao lɔ́ɔ tua-eeng dâi pen sǎn-yaan khɔ̌ɔng khwaam-chà-làat"),
  ("You misunderstood me; I didn't mean to criticize you.", "คุณเข้าใจฉันผิดแล้ว ฉันไม่ได้ตั้งใจจะติคุณ", "khun khâo-jai chǎn phìt lɛ́ɛo, chǎn mâi dâi tâng-jai jà tì khun"),
  ("Tell me the truth, are you joking or are you serious?", "บอกมาตรงๆ ล้อเล่นหรือพูดจริง?", "bɔ̀ɔk maa trong-trong, lɔ́ɔ-lên rʉ̌ʉ phûut jing?"),
  ("I could tell from his tone of voice that he was angry.", "ฉันรู้จากน้ำเสียงของเขาว่าเขาโกรธ", "chǎn rúu jàak nám-sǐang khɔ̌ɔng kháo wâa kháo kròot"),
  ("Marco said he was just joking, but nobody laughed.", "มาร์โกบอกว่าเขาแค่ล้อเล่น แต่ไม่มีใครหัวเราะ", "maa-koo bɔ̀ɔk wâa kháo khɛ̂ɛ lɔ́ɔ-lên, tɛ̀ɛ mâi mii khrai hǔa-rɔ́"),
  ("Speak in a gentler tone when you talk with customers. (formal)", "กรุณาใช้น้ำเสียงที่นุ่มนวลกว่านี้เวลาคุยกับลูกค้าด้วยค่ะ", "kà-rú-naa chái nám-sǐang thîi nûm-nuan kwàa níi wee-laa khui kàp lûuk-kháa dûai khâ"),
 ],
 "b2u6l4": [
  ("He tried to soften his words, but by then it was too late.", "เขาพยายามพูดให้อ่อนลง แต่ตอนนั้นก็สายเกินไปแล้ว", "kháo phá-yaa-yaam phûut hâi ɔ̀ɔn-long, tɛ̀ɛ tɔɔn-nán kɔ̂ɔ sǎai kəən-pai lɛ́ɛo"),
  ("Today's news made my doubts about this project even stronger.", "ข่าววันนี้ทำให้ฉันยิ่งสงสัยในโครงการนี้มากขึ้น", "khàao wan-níi tham-hâi chǎn yîng sǒng-sǎi nai khroong-kaan níi mâak khʉ̂n"),
  ("The movie was rather long, but I liked it.", "หนังค่อนข้างยาว แต่ฉันชอบนะ", "nǎng khɔ̂n-khâang yaao, tɛ̀ɛ chǎn chɔ̂ɔp ná"),
  ("Did you prepare enough to pass tomorrow's exam?", "คุณเตรียมตัวมาพอที่จะสอบผ่านพรุ่งนี้หรือยัง?", "khun triam-tua maa phɔɔ thîi jà sɔ̀ɔp phàan phrûng-níi rʉ̌ʉ-yang?"),
  ("I completely forgot my younger sister's birthday!", "ฉันลืมวันเกิดน้องสาวไปสนิทเลย!", "chǎn lʉʉm wan-kə̀ət nɔ́ɔng-sǎao pai sà-nìt ləəi!"),
  ("I don't feel like going out at all tonight.", "คืนนี้ฉันไม่อยากออกไปไหนเลย", "khʉʉn-níi chǎn mâi yàak ɔ̀ɔk pai nǎi ləəi"),
  ("Somehow we'll finish the work on time.", "ยังไงเราก็จะทำงานให้เสร็จทันเวลา", "yang-ngai rao kɔ̂ɔ jà tham-ngaan hâi sèt than wee-laa"),
  ("Italians usually eat dinner later than Thais.", "ปกติคนอิตาลีกินข้าวเย็นช้ากว่าคนไทย", "pà-kà-tì khon ì-taa-lii kin khâao-yen cháa kwàa khon-thai"),
  ("Renovating the house will take at least three months.", "การปรับปรุงบ้านจะใช้เวลาอย่างน้อยสามเดือน", "kaan pràp-prung bâan jà chái wee-laa yàang-nɔ́ɔi sǎam dʉan"),
  ("I'll tell you openly: your project, as it is now, doesn't work.", "ฉันจะบอกตรงๆ นะ โครงการของคุณในตอนนี้ใช้ไม่ได้", "chǎn jà bɔ̀ɔk trong-trong ná, khroong-kaan khɔ̌ɔng khun nai tɔɔn-níi chái mâi dâi"),
  ("Can you soften the tone of your email a little?", "ช่วยปรับน้ำเสียงในอีเมลให้นุ่มนวลขึ้นหน่อยได้ไหม?", "chûai pràp nám-sǐang nai ii-meo hâi nûm-nuan khʉ̂n nɔ̀i dâi mǎi?"),
  ("The boss said the situation was rather serious.", "หัวหน้าบอกว่าสถานการณ์ค่อนข้างร้ายแรง", "hǔa-nâa bɔ̀ɔk wâa sà-thǎa-ná-kaan khɔ̂n-khâang ráai-rɛɛng"),
 ],
 "b2u6x1": [
  ("That man gets involved in everything in the whole neighborhood.", "ผู้ชายคนนั้นชอบยุ่งเรื่องชาวบ้านไปทั่วทั้งซอย", "phûu-chaai khon nán chɔ̂ɔp yûng rʉ̂ang chaao-bâan pai thûa tháng sɔɔi"),
  ("I can vouch for him; he's a very honest person.", "ฉันรับรองเขาได้ เขาเป็นคนซื่อสัตย์มาก", "chǎn ráp-rɔɔng kháo dâi, kháo pen khon sʉ̂ʉ-sàt mâak"),
  ("My son is very stubborn; he doesn't listen to anyone.", "ลูกชายของฉันหัวดื้อมาก ไม่ฟังใครเลย", "lûuk-chaai khɔ̌ɔng chǎn hǔa-dʉ̂ʉ mâak, mâi fang khrai ləəi"),
  ("During the fire, nobody lost their head.", "ตอนไฟไหม้ไม่มีใครตื่นตระหนกจนขาดสติ", "tɔɔn fai-mâi mâi mii khrai tʉ̀ʉn-trà-nòk jon khàat-sà-tì"),
  ("Come on, tell me everything; I'm listening carefully.", "เอาเลย เล่ามาให้หมด ฉันตั้งใจฟังอยู่", "ao ləəi, lâo maa hâi mòt, chǎn tâng-jai fang yùu"),
  ("This time I'll turn a blind eye, but don't do it again.", "ครั้งนี้ฉันจะทำเป็นมองไม่เห็น แต่อย่าทำอีกนะ", "khráng-níi chǎn jà tham pen mɔɔng mâi hěn, tɛ̀ɛ yàa tham ìik ná"),
  ("I had to bite my tongue so I wouldn't answer him rudely.", "ฉันต้องข่มใจไว้ไม่ให้ตอบเขาไปแบบหยาบคาย", "chǎn tɔ̂ng khòm-jai wái mâi hâi tɔ̀ɔp kháo pai bɛ̀ɛp yàap-khaai"),
  ("My aunt talks too much; don't tell her anything!", "ป้าของฉันปากมาก อย่าเล่าอะไรให้ป้าฟังเด็ดขาด!", "pâa khɔ̌ɔng chǎn pàak-mâak, yàa lâo à-rai hâi pâa fang dèt-khàat!"),
  ("We have to grit our teeth for one more month.", "เราต้องกัดฟันสู้อีกเดือนหนึ่ง", "rao tɔ̂ng kàt-fan sûu ìik dʉan nʉ̀ng"),
  ("In hard times, my friends gave me a shoulder to lean on.", "ในยามลำบาก เพื่อนๆ เป็นที่พึ่งให้ฉัน", "nai yaam lam-bàak, phʉ̂an-phʉ̂an pen thîi-phʉ̂ng hâi chǎn"),
  ("When he needed help, everyone turned away from him.", "ตอนที่เขาต้องการความช่วยเหลือ ทุกคนก็หันหลังให้เขา", "tɔɔn thîi kháo tɔ̂ng-kaan khwaam-chûai-lʉ̌a, thúk-khon kɔ̂ɔ hǎn-lǎng hâi kháo"),
  ("He walked out of court with his head held high.", "เขาเดินออกจากศาลอย่างเชิดหน้า", "kháo dəən ɔ̀ɔk jàak sǎan yàang chə̂ət-nâa"),
 ],
 "b2u6x2": [
  ("At my colleagues' party I felt like an outsider.", "ที่งานปาร์ตี้ของเพื่อนร่วมงานฉันรู้สึกเหมือนเป็นคนนอก", "thîi ngaan-paa-tîi khɔ̌ɔng phʉ̂an-rûam-ngaan chǎn rúu-sʉ̀k mʉ̌an pen khon-nɔ̂ɔk"),
  ("By biking downtown, I killed two birds with one stone.", "การปั่นจักรยานเข้าเมืองทำให้ฉันยิงปืนนัดเดียวได้นกสองตัว", "kaan pàn jàk-kà-yaan khâo mʉang tham-hâi chǎn ying pʉʉn nát diao dâi nók sɔ̌ɔng tua"),
  ("Good luck with your interview tomorrow!", "ขอให้การสัมภาษณ์พรุ่งนี้ราบรื่นนะ!", "khɔ̌ɔ hâi kaan-sǎm-phâat phrûng-níi râap-rʉ̂ʉn ná!"),
  ("Watch out for that salesman; he's as sly as a fox.", "ระวังคนขายคนนั้นไว้ เขาเจ้าเล่ห์เหมือนสุนัขจิ้งจอก", "rá-wang khon-khǎai khon nán wái, kháo jâo-lêe mʉ̌an sù-nák-jîng-jɔ̀ɔk"),
  ("When I asked for the money, he pretended not to care.", "ตอนที่ฉันขอเงินคืน เขาทำเป็นไม่สนใจ", "tɔɔn thîi chǎn khɔ̌ɔ ngən khʉʉn, kháo tham pen mâi sǒn-jai"),
  ("When he decides something, he gets as stubborn as a donkey.", "พอตัดสินใจอะไรแล้ว เขาก็ดื้อเหมือนลา", "phɔɔ tàt-sǐn-jai à-rai lɛ́ɛo, kháo kɔ̂ɔ dʉ̂ʉ mʉ̌an laa"),
  ("I was so tired that I slept like the dead last night.", "ฉันเหนื่อยมากจนเมื่อคืนหลับเป็นตายเลย", "chǎn nʉ̀ai mâak jon mʉ̂a-khʉʉn làp pen taai ləəi"),
  ("Don't be a coward; talk to him yourself!", "อย่าขี้ขลาดสิ ไปคุยกับเขาเอง!", "yàa khîi-khlàat sì, pai khui kàp kháo eeng!"),
  ("Today the traffic downtown is moving as slowly as a turtle.", "วันนี้รถในเมืองวิ่งช้าเหมือนเต่าคลาน", "wan-níi rót nai mʉang wîng cháa mʉ̌an tào khlaan"),
  ("After the exams I feel as free as a bird.", "หลังสอบเสร็จฉันรู้สึกอิสระเหมือนนก", "lǎng sɔ̀ɔp sèt chǎn rúu-sʉ̀k ìt-sà-rà mʉ̌an nók"),
  ("My grandfather is ninety, but he's as healthy as a bull.", "ปู่อายุเก้าสิบแล้ว แต่ยังแข็งแรงเหมือนวัว", "pùu aa-yú kâo-sìp lɛ́ɛo, tɛ̀ɛ yang khɛ̌ng-rɛɛng mʉ̌an wua"),
  ("Don't be scared of what he says: he's just a dog barking at dry banana leaves.", "อย่ากลัวคำพูดของเขาเลย หมาเห่าใบตองแห้ง", "yàa klua kham-phûut khɔ̌ɔng kháo ləəi, mǎa hào bai-tɔɔng-hɛ̂ɛng"),
 ],
 "b2u6x3": [
  ("This job isn't to my liking; I'm looking for another one.", "งานนี้ไม่ถูกใจฉัน กำลังหางานใหม่อยู่", "ngaan níi mâi thùuk-jai chǎn, kam-lang hǎa ngaan mài yùu"),
  ("My older brother is a very good person; he always helps everyone.", "พี่ชายของฉันเป็นคนใจดีมาก ช่วยเหลือทุกคนเสมอ", "phîi-chaai khɔ̌ɔng chǎn pen khon jai-dii mâak, chûai-lʉ̌a thúk-khon sà-mə̌ə"),
  ("You want both things at once, but it doesn't work that way!", "คุณอยากได้ทั้งสองอย่างพร้อมกัน แต่มันไม่ได้ง่ายแบบนั้น!", "khun yàak dâi tháng sɔ̌ɔng yàang phrɔ́ɔm-kan, tɛ̀ɛ man mâi dâi ngâai bɛ̀ɛp nán!"),
  ("The smell of pad thai coming from the kitchen is making my mouth water.", "กลิ่นผัดไทยจากครัวทำให้ฉันน้ำลายสอ", "klìn phàt-thai jàak khrua tham-hâi chǎn nám-laai-sɔ̌ɔ"),
  ("That class was really very boring.", "คาบนั้นน่าเบื่อสุดๆ จริงๆ", "khâap nán nâa-bʉ̀a sùt-sùt jing-jing"),
  ("We'll accept any help with the move; everything comes in handy!", "เรื่องย้ายบ้านเรายินดีรับความช่วยเหลือทุกอย่าง อะไรก็มีประโยชน์หมด!", "rʉ̂ang yáai-bâan rao yin-dii ráp khwaam-chûai-lʉ̌a thúk yàang, à-rai kɔ̂ɔ mii prà-yòot mòt!"),
  ("Your help came at just the right time, thanks!", "คุณช่วยได้ทันเวลาพอดีเลย ขอบคุณนะ!", "khun chûai dâi than wee-laa phɔɔ-dii ləəi, khɔ̀ɔp-khun ná!"),
  ("This scarf goes really well with your coat.", "ผ้าพันคอผืนนี้เข้ากับเสื้อโค้ทของคุณมาก", "phâa-phan-khɔɔ phʉ̌ʉn níi khâo kàp sʉ̂a-khóot khɔ̌ɔng khun mâak"),
  ("Do you have the courage to tell the boss the truth in front of everyone?", "คุณกล้าบอกความจริงกับหัวหน้าต่อหน้าทุกคนไหม?", "khun klâa bɔ̀ɔk khwaam-jing kàp hǔa-nâa tɔ̀ɔ-nâa thúk-khon mǎi?"),
  ("They're cooking something up; for some reason everyone is quiet.", "พวกเขาต้องกำลังวางแผนอะไรกันอยู่แน่ๆ ทุกคนเงียบผิดปกติ", "phûak-kháo tɔ̂ng kam-lang waang-phɛ̌ɛn à-rai kan yùu nɛ̂ɛ-nɛ̂ɛ, thúk-khon ngîap phìt-pà-kà-tì"),
  ("This idea isn't your own; you heard it from someone!", "ความคิดนี้ไม่ใช่ของคุณเอง คุณได้ยินมาจากใครสักคนแน่!", "khwaam-khít níi mâi châi khɔ̌ɔng khun eeng, khun dâi-yin maa jàak khrai sàk khon nɛ̂ɛ!"),
  ("When the water rises, hurry and scoop it up: sign up for the course right now!", "น้ำขึ้นให้รีบตัก สมัครคอร์สเลยตอนนี้!", "náam khʉ̂n hâi rîip tàk, sà-màk khɔ́ɔt ləəi tɔɔn-níi!"),
 ],
 "b2u6x4": [
  ("It's unbelievable, he paid a thousand euros for a phone!", "ไม่น่าเชื่อเลย เขาจ่ายเงินพันยูโรซื้อโทรศัพท์เครื่องเดียว!", "mâi nâa-chʉ̂a ləəi, kháo jàai ngən phan yuu-roo sʉ́ʉ thoo-rá-sàp khrʉ̂ang diao!"),
  ("What a mess your younger brother left in the kitchen after breakfast!", "หลังกินข้าวเช้าน้องชายคุณทิ้งครัวไว้รกขนาดไหนเนี่ย!", "lǎng kin khâao-cháao nɔ́ɔng-chaai khun thíng khrua wái rók khà-nàat nǎi nîa!"),
  ("I'm dying of hunger; let's go eat something.", "หิวจะตายอยู่แล้ว ไปหาอะไรกินกันเถอะ", "hǐu jà taai yùu lɛ́ɛo, pai hǎa à-rai kin kan thə̀"),
  ("Yesterday's concert was really awesome!", "คอนเสิร์ตเมื่อวานสุดยอดจริงๆ!", "khɔn-sə̀ət mʉ̂a-waan sùt-yɔ̂ɔt jing-jing!"),
  ("What I mean is, I didn't understand what you want from me.", "คือว่าฉันไม่เข้าใจว่าคุณต้องการอะไรจากฉัน", "khʉʉ wâa chǎn mâi khâo-jai wâa khun tɔ̂ng-kaan à-rai jàak chǎn"),
  ("Fine, if you don't want to come with us, I'll go to the movies by myself.", "ก็ได้ ถ้าไม่อยากไปกับเราฉันก็จะไปดูหนังคนเดียว", "kɔ̂ɔ dâi, thâa mâi yàak pai kàp rao chǎn kɔ̂ɔ jà pai duu nǎng khon-diao"),
  ("Oh, come on, I don't believe you really won!", "โธ่ ไม่เชื่อหรอกว่าคุณชนะจริงๆ!", "thôo, mâi chʉ̂a rɔ̀ɔk wâa khun chá-ná jing-jing!"),
  ("Lending him my car again wouldn't even cross my mind!", "ฉันไม่เคยคิดจะให้เขายืมรถอีกเลยแม้แต่นิดเดียว!", "chǎn mâi khəəi khít jà hâi kháo yʉʉm rót ìik ləəi mɛ́ɛ-tɛ̀ɛ nít-diao!"),
  ("The new job is going great; I'm very happy!", "งานใหม่ไปได้สวย ดีใจมาก!", "ngaan mài pai dâi sǔai, dii-jai mâak!"),
  ("We're having a simple dinner; come, you all, and don't be shy.", "เราแค่กินข้าวเย็นง่ายๆ มากันได้เลยทุกคนไม่ต้องเกรงใจ", "rao khɛ̂ɛ kin khâao-yen ngâai-ngâai, maa kan dâi ləəi thúk-khon mâi tɔ̂ng kreeng-jai"),
  ("As always, he finished the project at the last minute.", "เขาทำโครงการเสร็จนาทีสุดท้ายเหมือนเดิม", "kháo tham khroong-kaan sèt naa-thii sùt-tháai mʉ̌an-dəəm"),
  ("Wait here; I'll be back in a moment.", "รอตรงนี้นะ เดี๋ยวกลับมา", "rɔɔ trong-níi ná, dǐao klàp maa"),
 ],
 "b2u6x5": [
  ("His biting joke ruined the pleasant atmosphere at dinner.", "มุกแรงๆ ของเขาทำให้บรรยากาศดีๆ ตอนกินข้าวเย็นเสียหมด", "múk rɛɛng-rɛɛng khɔ̌ɔng kháo tham-hâi ban-yaa-kàat dii-dii tɔɔn kin khâao-yen sǐa mòt"),
  ("Not everyone likes dark humor, especially strangers.", "ไม่ใช่ทุกคนจะชอบมุกตลกร้าย โดยเฉพาะคนแปลกหน้า", "mâi châi thúk-khon jà chɔ̂ɔp múk tà-lòk-ráai, dooi-chà-phɔ́ khon plɛ̀ɛk-nâa"),
  ("Stop your mocking; it's not funny!", "เลิกเยาะเย้ยได้แล้ว ไม่ตลกเลย!", "lə̂ək yɔ́-yə́əi dâi lɛ́ɛo, mâi tà-lòk ləəi!"),
  ("That was a nasty joke; someone could have gotten hurt.", "แกล้งกันแบบนั้นมันเกินไป อาจมีคนเจ็บได้", "klɛ̂ɛng kan bɛ̀ɛp nán man kəən-pai, àat mii khon jèp dâi"),
  ("Don't try to act sweet with me; I know what you want.", "ไม่ต้องมาทำหวานใส่ฉันหรอก ฉันรู้ว่าคุณต้องการอะไร", "mâi tɔ̂ng maa tham wǎan sài chǎn rɔ̀ɔk, chǎn rúu wâa khun tɔ̂ng-kaan à-rai"),
  ("If the timing of a joke isn't right, even the best line isn't funny.", "ถ้าจังหวะของมุกไม่ใช่ ต่อให้เป็นมุกที่ดีที่สุดก็ไม่ตลก", "thâa jang-wà khɔ̌ɔng múk mâi châi, tɔ̀ɔ-hâi pen múk thîi dii thîi-sùt kɔ̂ɔ mâi tà-lòk"),
  ("The title of the article is a very clever play on words.", "ชื่อบทความเป็นการเล่นคำที่ฉลาดมาก", "chʉ̂ʉ bòt-khwaam pen kaan-lên-kham thîi chà-làat mâak"),
  ("My dad always makes corny jokes that only make him laugh.", "พ่อชอบเล่นมุกฝืดๆ ที่ขำอยู่คนเดียว", "phɔ̂ɔ chɔ̂ɔp lên múk fʉ̀ʉt-fʉ̀ʉt thîi khǎm yùu khon-diao"),
  ("His laugh is contagious: when he laughs, everyone laughs.", "เสียงหัวเราะของเขาติดกันง่าย พอเขาหัวเราะทุกคนก็หัวเราะตาม", "sǐang-hǔa-rɔ́ khɔ̌ɔng kháo tìt kan ngâai, phɔɔ kháo hǔa-rɔ́ thúk-khon kɔ̂ɔ hǔa-rɔ́ taam"),
  ("Despite her forced smile, you could see that she was upset.", "ถึงเธอจะฝืนยิ้ม แต่ก็ดูออกว่าเธอไม่สบายใจ", "thʉ̌ng thəə jà fʉ̌ʉn yím, tɛ̀ɛ kɔ̂ɔ duu ɔ̀ɔk wâa thəə mâi sà-baai-jai"),
  ("I hinted to him several times, but he didn't get the hint.", "ฉันพูดเป็นนัยกับเขาหลายครั้ง แต่เขาไม่เข้าใจสักที", "chǎn phûut pen-nai kàp kháo lǎai khráng, tɛ̀ɛ kháo mâi khâo-jai sàk-thii"),
  ("He gets offended easily, so choose your words carefully.", "เขาเป็นคนขี้น้อยใจ เพราะฉะนั้นเลือกคำพูดให้ดีๆ นะ", "kháo pen khon khîi-nɔ́ɔi-jai, phrɔ́-chà-nán lʉ̂ak kham-phûut hâi dii-dii ná"),
 ],
 "b2u6x6": [
  ("The aforementioned document must be signed by Friday.", "เอกสารดังกล่าวจะต้องได้รับการลงนามภายในวันศุกร์", "èek-kà-sǎan dang-klàao jà tɔ̂ng dâi-ráp kaan-long-naam phaai-nai wan-sùk"),
  ("In addition, a copy of the passport is also required.", "นอกจากนี้ ยังต้องใช้สำเนาหนังสือเดินทางด้วย", "nɔ̂ɔk-jàak-níi, yang tɔ̂ng chái sǎm-nao nǎng-sʉ̌ʉ-dəən-thaang dûai"),
  ("The proposal is interesting; nevertheless, the costs are very high.", "ข้อเสนอนี้น่าสนใจ อย่างไรก็ตามค่าใช้จ่ายสูงมาก", "khɔ̂ɔ-sà-nə̌ə níi nâa-sǒn-jai, yàang-rai-kɔ̂ɔ-taam khâa-chái-jàai sǔung mâak"),
  ("The letter was sent to all employees so that everyone knows the new rules.", "จดหมายถูกส่งถึงพนักงานทุกคนเพื่อให้ทุกคนทราบระเบียบใหม่", "jòt-mǎai thùuk sòng thʉ̌ng phá-nák-ngaan thúk-khon phʉ̂a hâi thúk-khon sâap rá-bìap mài"),
  ("In order to avoid delays, we ask you to arrive early. (formal)", "เพื่อหลีกเลี่ยงความล่าช้า ขอความกรุณาท่านมาถึงก่อนเวลาครับ", "phʉ̂a lìik-lîang khwaam-lâa-cháa, khɔ̌ɔ khwaam-kà-rú-naa thân maa thʉ̌ng kɔ̀ɔn wee-laa khráp"),
  ("Access to the archive is allowed only with prior authorization.", "การเข้าใช้ห้องเก็บเอกสารอนุญาตเฉพาะผู้ที่ได้รับอนุญาตล่วงหน้าเท่านั้น", "kaan khâo chái hɔ̂ng-kèp-èek-kà-sǎan à-nú-yâat chà-phɔ́ phûu thîi dâi-ráp à-nú-yâat lûang-nâa thâo-nán"),
  ("In practice, the decision had been made before the meeting.", "ในทางปฏิบัติ การตัดสินใจเกิดขึ้นก่อนการประชุมแล้ว", "nai thaang pà-tì-bàt, kaan-tàt-sǐn-jai kə̀ət-khʉ̂n kɔ̀ɔn kaan-prà-chum lɛ́ɛo"),
  ("First of all, I would like to thank everyone present.", "ก่อนอื่น ผมขอขอบคุณทุกท่านที่มาในวันนี้", "kɔ̀ɔn-ʉ̀ʉn, phǒm khɔ̌ɔ khɔ̀ɔp-khun thúk thân thîi maa nai wan-níi"),
  ("What is the procedure for getting a visa?", "ขั้นตอนการขอวีซ่าเป็นอย่างไร?", "khân-tɔɔn kaan-khɔ̌ɔ wii-sâa pen yàang-rai?"),
  ("Parliament ratified the treaty unanimously.", "รัฐสภาให้สัตยาบันสนธิสัญญาด้วยมติเอกฉันท์", "rát-thà-sà-phaa hâi-sàt-tà-yaa-ban sǒn-thí-sǎn-yaa dûai má-tì èek-kà-chǎn"),
  ("This matter is not within our competence.", "เรื่องนี้ไม่อยู่ในอำนาจหน้าที่ของเรา", "rʉ̂ang níi mâi yùu nai am-nâat nâa-thîi khɔ̌ɔng rao"),
  ("Keeping the status quo isn't always the wisest choice.", "การรักษาสถานะเดิมไว้ไม่ใช่ทางเลือกที่ฉลาดที่สุดเสมอไป", "kaan rák-sǎa sà-thǎa-ná-dəəm wái mâi châi thaang-lʉ̂ak thîi chà-làat thîi-sùt sà-mə̌ə pai"),
 ],
 "b2u6x7": [
  ("If you'll allow me, your plan has some weak points. (formal)", "ขออนุญาตนะครับ แผนของคุณยังมีจุดอ่อนอยู่บ้าง", "khɔ̌ɔ-à-nú-yâat ná khráp, phɛ̌ɛn khɔ̌ɔng khun yang mii jùt-ɔ̀ɔn yùu bâang"),
  ("If I'm not mistaken, the meeting was scheduled for ten o'clock.", "ถ้าจำไม่ผิด การประชุมนัดไว้ตอนสิบโมง", "thâa jam mâi phìt, kaan-prà-chum nát wái tɔɔn sìp moong"),
  ("Allow me to say: the situation is much more complicated than that. (formal)", "ขอพูดหน่อยนะคะ สถานการณ์ซับซ้อนกว่านั้นมาก", "khɔ̌ɔ phûut nɔ̀i ná khá, sà-thǎa-ná-kaan sáp-sɔ́ɔn kwàa nán mâak"),
  ("Unfortunately, it seems your flight has been canceled because of bad weather. (formal)", "น่าเสียดายค่ะ ดูเหมือนว่าเที่ยวบินของคุณจะถูกยกเลิกเพราะสภาพอากาศไม่ดี", "nâa-sǐa-daai khâ, duu-mʉ̌an wâa thîao-bin khɔ̌ɔng khun jà thùuk yók-lə̂ək phrɔ́ sà-phâap-aa-kàat mâi dii"),
  ("Unfortunately, this time I have to decline your invitation. (formal)", "เสียดายจริงๆ ครับ ครั้งนี้ผมคงต้องขอปฏิเสธคำเชิญของคุณ", "sǐa-daai jing-jing khráp, khráng-níi phǒm khong tɔ̂ng khɔ̌ɔ pà-tì-sèet kham-chəən khɔ̌ɔng khun"),
  ("That's not quite right; the data shows something else.", "ไม่ใช่อย่างนั้นซะทีเดียว ข้อมูลบอกอีกอย่างหนึ่ง", "mâi châi yàang nán sá thii-diao, khɔ̂ɔ-muun bɔ̀ɔk ìik yàang nʉ̀ng"),
  ("In a sense, you're right too, but it's not all that simple.", "ในแง่หนึ่งคุณก็พูดถูก แต่มันไม่ได้ง่ายขนาดนั้น", "nai ngɛ̂ɛ nʉ̀ng khun kɔ̂ɔ phûut thùuk, tɛ̀ɛ man mâi dâi ngâai khà-nàat nán"),
  ("Perhaps it would be better to postpone the decision until next week.", "บางทีอาจจะดีกว่าถ้าเลื่อนการตัดสินใจไปสัปดาห์หน้า", "baang-thii àat jà dii kwàa thâa lʉ̂an kaan-tàt-sǐn-jai pai sàp-daa nâa"),
  ("It would be advisable to notify the clients in advance.", "การแจ้งลูกค้าล่วงหน้าน่าจะเป็นการดี", "kaan jɛ̂ɛng lûuk-kháa lûang-nâa nâa-jà pen kaan dii"),
  ("If you don't mind, could you close the window? (formal)", "ถ้าไม่เป็นการรบกวน ช่วยปิดหน้าต่างให้หน่อยได้ไหมคะ?", "thâa mâi pen-kaan-róp-kuan, chûai pìt nâa-tàang hâi nɔ̀i dâi mǎi khá?"),
  ("I apologize for the inconvenience caused by the delay.", "ขออภัยในความไม่สะดวกที่เกิดจากความล่าช้า", "khɔ̌ɔ-à-phai nai khwaam-mâi-sà-dùak thîi kə̀ət jàak khwaam-lâa-cháa"),
  ("Thank you for your patience; I look forward to your reply. (formal)", "ขอบคุณสำหรับความอดทน และหวังว่าจะได้รับคำตอบจากท่านครับ", "khɔ̀ɔp-khun sǎm-ràp khwaam-òt-thon, lɛ́ wǎng wâa jà dâi-ráp kham-tɔ̀ɔp jàak thân khráp"),
 ],
 "b2u6x8": [
  ("Are you absolutely sure you closed the door when you left the house?", "คุณแน่ใจเต็มร้อยเลยเหรอว่าปิดประตูตอนออกจากบ้าน?", "khun nɛ̂ɛ-jai tem-rɔ́ɔi ləəi rə̌ə wâa pìt prà-tuu tɔɔn ɔ̀ɔk jàak bâan?"),
  ("I am firmly against the idea of selling the house.", "ฉันคัดค้านความคิดที่จะขายบ้านอย่างเด็ดขาด", "chǎn khát-kháan khwaam-khít thîi jà khǎai bâan yàang dèt-khàat"),
  ("The view from the mountain was extremely beautiful.", "วิวจากบนภูเขาสวยเป็นอย่างยิ่ง", "wiu jàak bon phuu-khǎo sǔai pen yàang yîng"),
  ("I like Italy a lot, especially its southern cuisine.", "ฉันชอบอิตาลีมาก โดยเฉพาะอาหารทางใต้", "chǎn chɔ̂ɔp ì-taa-lii mâak, dooi-chà-phɔ́ aa-hǎan thaang tâi"),
  ("This year prices rose significantly.", "ปีนี้ราคาสินค้าเพิ่มขึ้นอย่างเห็นได้ชัด", "pii níi raa-khaa sǐn-kháa phə̂əm-khʉ̂n yàang hěn dâi chát"),
  ("Today's soup turned out slightly salty, but it's very tasty.", "แกงจืดวันนี้เค็มไปนิด แต่อร่อยมาก", "kɛɛng-jʉ̀ʉt wan-níi khem pai nít, tɛ̀ɛ à-rɔ̀i mâak"),
  ("This morning I barely caught the train.", "เช้านี้ฉันขึ้นรถไฟทันแบบเฉียดฉิว", "cháao níi chǎn khʉ̂n rót-fai than bɛ̀ɛp chìat-chǐu"),
  ("Essentially, the main problem is the lack of time.", "โดยพื้นฐานแล้ว ปัญหาหลักคือการขาดเวลา", "dooi phʉ́ʉn-thǎan lɛ́ɛo, pan-hǎa làk khʉʉ kaan khàat wee-laa"),
  ("The work is practically finished; only the signature is left.", "งานแทบจะเสร็จแล้ว เหลือแค่ลายเซ็น", "ngaan thɛ̂ɛp jà sèt lɛ́ɛo, lʉ̌a khɛ̂ɛ laai-sen"),
  ("I can barely read what he writes by hand.", "ลายมือของเขาฉันแทบอ่านไม่ออก", "laai-mʉʉ khɔ̌ɔng kháo chǎn thɛ̂ɛp àan mâi ɔ̀ɔk"),
  ("At the very least, you could have called me!", "อย่างน้อยก็น่าจะโทรมาบอกฉันหน่อย!", "yàang-nɔ́ɔi kɔ̂ɔ nâa-jà thoo maa bɔ̀ɔk chǎn nɔ̀i!"),
  ("The meeting went on well beyond the planned two hours.", "การประชุมยืดเยื้อเกินสองชั่วโมงที่วางแผนไว้ไปมาก", "kaan-prà-chum yʉ̂ʉt-yʉ́a kəən sɔ̌ɔng chûa-moong thîi waang-phɛ̌ɛn wái pai mâak"),
 ],
 "b2u6x9": [
  ("In short, the trip went well, but it was very tiring.", "สรุปก็คือการเดินทางราบรื่นดี แต่เหนื่อยมาก", "sà-rùp kɔ̂ɔ khʉʉ kaan-dəən-thaang râap-rʉ̂ʉn dii, tɛ̀ɛ nʉ̀ai mâak"),
  ("Well, anyway, let's talk about something else: how's your mom?", "เอาล่ะ คุยเรื่องอื่นกันดีกว่า แม่คุณเป็นยังไงบ้าง?", "ao lâ, khui rʉ̂ang ʉ̀ʉn kan dii-kwàa, mɛ̂ɛ khun pen yang-ngai bâang?"),
  ("By the way, yesterday at the market I ran into your old school teacher.", "อ้อ เมื่อวานฉันเจอครูเก่าสมัยเรียนของคุณที่ตลาด", "ɔ̂ɔ, mʉ̂a-waan chǎn jəə khruu kào sà-mǎi rian khɔ̌ɔng khun thîi tà-làat"),
  ("I prefer walking to taking the bus.", "ฉันชอบเดินมากกว่านั่งรถเมล์", "chǎn chɔ̂ɔp dəən mâak-kwàa nâng rót-mee"),
  ("Instead of complaining, try to find a solution.", "แทนที่จะบ่น ลองหาทางแก้ดู", "thɛɛn-thîi jà bòn, lɔɔng hǎa thaang-kɛ̂ɛ duu"),
  ("Don't insist; I won't change my mind anyway.", "ไม่ต้องตื๊อหรอก ยังไงฉันก็ไม่เปลี่ยนใจ", "mâi tɔ̂ng tʉ́ʉ rɔ̀ɔk, yang-ngai chǎn kɔ̂ɔ mâi plìan-jai"),
  ("At least let me know when you get home!", "ถึงบ้านแล้วอย่างน้อยก็ส่งข่าวมาบอกหน่อยนะ!", "thʉ̌ng bâan lɛ́ɛo yàang-nɔ́ɔi kɔ̂ɔ sòng khàao maa bɔ̀ɔk nɔ̀i ná!"),
  ("After all, it's just a game; don't get angry.", "ยังไงมันก็แค่เกม อย่าโกรธเลย", "yang-ngai man kɔ̂ɔ khɛ̂ɛ keem, yàa kròot ləəi"),
  ("Funny coincidence: when it's time to pay, he's never around.", "บังเอิญจังนะ พอถึงเวลาจ่ายเงินทีไรเขาไม่เคยอยู่เลย", "bang-əən jang ná, phɔɔ thʉ̌ng wee-laa jàai ngən thii-rai kháo mâi khəəi yùu ləəi"),
  ("Who knows if Somchai will remember my birthday.", "ใครจะไปรู้ว่าสมชายจะจำวันเกิดฉันได้ไหม", "khrai jà pai rúu wâa sǒm-chaai jà jam wan-kə̀ət chǎn dâi mǎi"),
  ("To be honest, I didn't expect such a good result.", "พูดตามตรง ฉันไม่คิดว่าผลจะออกมาดีขนาดนี้", "phûut taam-trong, chǎn mâi khít wâa phǒn jà ɔ̀ɔk-maa dii khà-nàat níi"),
  ("The fact is that the project is running a month late.", "ความจริงก็คือโครงการล่าช้าไปหนึ่งเดือนแล้ว", "khwaam-jing kɔ̂ɔ khʉʉ khroong-kaan lâa-cháa pai nʉ̀ng dʉan lɛ́ɛo"),
 ],
 "b2u6x10": [
  ("You're late, but better late than never!", "มาสายนะ แต่มาช้ายังดีกว่าไม่มา!", "maa sǎai ná, tɛ̀ɛ maa cháa yang dii kwàa mâi maa!"),
  ("He promised a lot, but there's a big difference between words and deeds.", "เขาสัญญาไว้เยอะ แต่คำพูดกับการกระทำต่างกันมาก", "kháo sǎn-yaa wái yə́, tɛ̀ɛ kham-phûut kàp kaan-krà-tham tàang kan mâak"),
  ("Don't trust appearances: shiny on the outside, hollow on the inside.", "อย่าเชื่อแค่ภายนอก ข้างนอกสุกใสข้างในเป็นโพรง", "yàa chʉ̂a khɛ̂ɛ phaai-nɔ̂ɔk, khâang-nɔ̂ɔk sùk-sǎi khâang-nai pen phroong"),
  ("Keep looking for a job: where there's effort, there's success.", "หางานต่อไป ความพยายามอยู่ที่ไหนความสำเร็จอยู่ที่นั่น", "hǎa ngaan tɔ̀ɔ pai, khwaam-phá-yaa-yaam yùu thîi-nǎi khwaam-sǎm-rèt yùu thîi-nân"),
  ("He who laughs last laughs best; we'll see later who was right.", "ใครหัวเราะทีหลังดังกว่า เดี๋ยวก็รู้ว่าใครถูก", "khrai hǔa-rɔ́ thii-lǎng dang kwàa, dǐao kɔ̂ɔ rúu wâa khrai thùuk"),
  ("Don't judge him by his clothes; clothes don't define a person.", "อย่าตัดสินเขาจากการแต่งตัว เสื้อผ้าไม่ได้บอกว่าคนเป็นอย่างไร", "yàa tàt-sǐn kháo jàak kaan-tɛ̀ng-tua, sʉ̂a-phâa mâi dâi bɔ̀ɔk wâa khon pen yàang-rai"),
  ("One top grade is nice, but don't count your chickens before they hatch.", "ได้เกรดเอหนึ่งวิชาก็ดีใจอยู่หรอก แต่อย่าเพิ่งนับลูกไก่ก่อนไข่จะฟัก", "dâi krèet ee nʉ̀ng wí-chaa kɔ̂ɔ dii-jai yùu rɔ̀ɔk, tɛ̀ɛ yàa phə̂ng náp lûuk-kài kɔ̀ɔn khài jà fák"),
  ("When you're abroad, remember: when in Rome, do as the Romans do.", "เวลาอยู่ต่างประเทศ จำไว้ว่าเข้าเมืองตาหลิ่วต้องหลิ่วตาตาม", "wee-laa yùu tàang-prà-thêet, jam wái wâa khâo-mʉang-taa-lìu tɔ̂ng lìu-taa taam"),
  ("He didn't answer: silence means consent.", "เขาไม่ตอบ ความเงียบก็คือการยอมรับ", "kháo mâi tɔ̀ɔp, khwaam-ngîap kɔ̂ɔ khʉʉ kaan-yɔɔm-ráp"),
  ("Don't complain about the gift: you shouldn't find fault with what you're given.", "อย่าบ่นเรื่องของขวัญเลย ของที่คนอื่นให้มาไม่ควรไปติ", "yàa bòn rʉ̂ang khɔ̌ɔng-khwǎn ləəi, khɔ̌ɔng thîi khon ʉ̀ʉn hâi maa mâi khuan pai tì"),
  ("There's a lesson in everything: thanks to that mistake I learned a lot.", "ทุกเรื่องมีบทเรียน ความผิดพลาดครั้งนั้นทำให้ฉันได้เรียนรู้อะไรเยอะมาก", "thúk rʉ̂ang mii bòt-rian, khwaam-phìt-phlâat khráng nán tham-hâi chǎn dâi rian-rúu à-rai yə́ mâak"),
  ("Time will reveal the truth; in the end everything will come out.", "เวลาจะพิสูจน์ความจริง สุดท้ายทุกอย่างก็จะปรากฏ", "wee-laa jà phí-sùut khwaam-jing, sùt-tháai thúk-yàang kɔ̂ɔ jà praa-kòt"),
 ],
}
